def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_def = 0
    opp_def = 0
    for a, b in history:
        if a == 'D':
            my_def += 1
        if b == 'D':
            opp_def += 1
    opp_c = n - opp_def

    if opp_def == n:
        return 'D'
    if opp_c * 2 < n:
        return 'D'

    forgive = 0
    punish = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i+1][1] == 'C':
                forgive += 1
            else:
                punish += 1

    last_my, last_opp = history[-1]

    if my_def == 0:
        if opp_def == 0:
            if n < 5:
                return 'C'
            return 'D'
        else:
            if last_opp == 'D':
                return 'D'
            return 'C'

    if forgive >= 3 and punish == 0:
        return 'D'

    if forgive > punish and forgive >= 1:
        if last_opp == 'D':
            return 'C'
        if last_my == 'C':
            return 'D'
        else:
            return 'C'

    if last_opp == 'D':
        if last_my == 'C':
            return 'D'
        else:
            return 'C'
    return 'C'
